using System.Reflection;
using NetArchTest.Rules;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

public sealed class LayerDependencyTests
{
    private static readonly Assembly DomainAssembly = typeof(Money).Assembly;
    private static readonly Assembly ApplicationAssembly = typeof(IPaymentGateway).Assembly;
    private static readonly Assembly InfrastructureAssembly = typeof(HttpPaymentGateway).Assembly;

    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO", "System.Net", "System.Data", "System.Text.Json", "Microsoft.Data", "Microsoft.EntityFrameworkCore",
    ];

    [Fact]
    public void Domain_does_not_depend_on_other_layers()
        => AssertNoDependency(DomainAssembly, "PaymentAuthorization.Application", "PaymentAuthorization.Infrastructure");

    [Fact]
    public void Application_does_not_depend_on_infrastructure()
        => AssertNoDependency(ApplicationAssembly, "PaymentAuthorization.Infrastructure");

    [Fact]
    public void Domain_does_not_use_technical_details()
        => AssertNoDependency(DomainAssembly, TechnicalNamespaces);

    [Fact]
    public void Application_does_not_use_technical_details()
        => AssertNoDependency(ApplicationAssembly, TechnicalNamespaces);

    private static void AssertNoDependency(Assembly assembly, params string[] forbidden)
    {
        var result = Types.InAssembly(assembly).That().ResideInNamespaceStartingWith("PaymentAuthorization")
            .ShouldNot().HaveDependencyOnAny(forbidden).GetResult();

        Assert.True(result.IsSuccessful,
            $"Forbidden dependency in: {string.Join(", ", result.FailingTypeNames ?? [])}");
    }
}
